using HospitalityOS.SharedKernel.Domain;
using HospitalityOS.SharedKernel.Tenancy;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace HospitalityOS.Adapters.EfCore.Configurations;

/// <summary>
/// Mapping shared by every aggregate: its own table, the ID as key (never generated by the database), the tenant,
/// and <see cref="IAggregateRoot.Version"/> as the optimistic concurrency token. Raised events are not columns;
/// the unit of work takes them on commit.
/// </summary>
internal static class AggregateMapping
{
    public static EntityTypeBuilder<TAggregate> MapAggregate<TAggregate>(this EntityTypeBuilder<TAggregate> builder, string table)
        where TAggregate : class, IAggregateRoot, ITenantScoped
    {
        // By name: Id is declared on the generic base class and TenantId on an interface.
        builder.ToTable(table);
        builder.HasKey("Id");
        builder.Property("Id").ValueGeneratedNever();
        builder.Property(nameof(ITenantScoped.TenantId));
        builder.HasIndex(nameof(ITenantScoped.TenantId));
        builder.Property(nameof(IAggregateRoot.Version)).IsConcurrencyToken();
        builder.Ignore(nameof(IAggregateRoot.DomainEvents));

        return builder;
    }
}
